import{_ as o,l as n,o as e,c as i,v as t,p as l,x as s,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SSH 密钥认证","description":"","frontmatter":{"title":"SSH 密钥认证","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssh-keys-auth.md","filePath":"cs/ssh-keys-auth.md","lastUpdated":1789023840000}'),p={name:"cs/ssh-keys-auth.md"};function S(E,a,A,_,u,m){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="ssh-密钥认证" tabindex="-1">SSH 密钥认证 <a class="header-anchor" href="#ssh-密钥认证" aria-label="Permalink to &quot;SSH 密钥认证&quot;">​</a></h1><div class="epigraph"><p>SSH 用主机钥钉服务器身份，用用户钥或证书代替口令。agent 转发、已知主机文件与授权文件的权限，比再选一种分组密码更能决定这次登录是否被掉包。</p><footer>—— RFC 4251–4254；Ylonen and Lonvick；对照 OpenSSH 的认证模型</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/tls-attack-history">TLS 攻击史</a>收的是 Web 信道。缺口是<strong>运维信道</strong>：SSH 不走 PKI 浏览器锚，而走 first-contact TOFU 与 <code>authorized_keys</code>。不重写 AEAD。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口令登录把<a href="/cs/password-salt">口令与加盐</a>问题搬到每个 sshd。公钥认证：用户持签钥，服务器存公钥。主机钥不匹配应中止——TOFU 在第一次无法防中间人。缺口是信任启动与 agent 的委托范围，不是再讲握手字节。</p><h3 id="不要转发-agent-到不可信跳板" tabindex="-1">不要转发 agent 到不可信跳板 <a class="header-anchor" href="#不要转发-agent-到不可信跳板" aria-label="Permalink to &quot;不要转发 agent 到不可信跳板&quot;">​</a></h3><p>agent 转发等于把签名能力借出。跳板被占则用户钥被当签具。</p><p><span class="marginnote">RFC 4252 认证。OpenSSH 证书是另一 CA 模型，与 X.509 平行。本课不写暴力破口令的字表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分主机认证与用户认证。known_hosts 钉指纹；CA 签主机钥可规模化。权限：<code>.ssh</code> 过宽则密钥文件被换。对照 WireGuard：双方静态钥，模型更简单。</p>',12)),(e(),l(c,null,{default:s(()=>[h(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HK%5B%22%E4%B8%BB%E6%9C%BA%E9%92%A5%20TOFU%2FCA%22%5D%20--%3E%20SESS%5B%22%E4%BC%9A%E8%AF%9D%E5%AF%86%E9%92%A5%22%5D%0A%20%20UK%5B%22%E7%94%A8%E6%88%B7%E7%AD%BE%E9%92%A5%22%5D%20--%3E%20AUTH%5B%22authorized_keys%22%5D%0A%20%20AUTH%20--%3E%20SESS%0A%20%20AGENT%5B%22agent%22%5D%20-.-%3E%7C%22%E8%BD%AC%E5%8F%91%3D%E5%80%9F%E5%87%BA%E7%AD%BE%E5%90%8D%22%7C%20RISK%5B%22%E8%B7%B3%E6%9D%BF%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>管理面是高价值会话：一次登录等于 root 路径。密钥口令短语与硬件令牌把签钥关进第二因素。下一课 IPsec：网关到网关的 SA，不是交互式 shell。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部 KEX 算法列菜单。IPsec 与 IKE 下一课：UDP 上的协商与 SPD。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TLS 服务万维网；SSH 钉运维身份。</li><li>主机钥 TOFU 弱在第一次；用户钥代替口令。</li><li>agent 转发是委托，不是免费便利。</li><li>下一课 IPsec 与 IKE。</li><li>出处：RFC 4251–4254；OpenSSH 手册；对照 Anderson 对 TOFU。</li></ul>',8))])}const B=o(p,[["render",S]]);export{f as __pageData,B as default};
